import{_ as s,o as n,c as e,ai as p}from"./chunks/framework.Ba-VnP44.js";const o=JSON.parse('{"title":"变更控制","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/03-quality/change-control.md","filePath":"ai/productivity/dev-spec/03-quality/change-control.md"}'),l={name:"ai/productivity/dev-spec/03-quality/change-control.md"};function i(t,a,r,c,d,b){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="变更控制" tabindex="-1">变更控制 <a class="header-anchor" href="#变更控制" aria-label="Permalink to “变更控制”">​</a></h1><blockquote><p>第三层 · 质量保障。解决「怎么控制改动范围、让每一步可追踪可回退」——修改范围三栏、检查点、失败分类、遗留文件清理都在这里统一约束。</p></blockquote><h2 id="贯穿全流程的定位" tabindex="-1">贯穿全流程的定位 <a class="header-anchor" href="#贯穿全流程的定位" aria-label="Permalink to “贯穿全流程的定位”">​</a></h2><p>变更控制从需求阶段定边界开始，贯穿开发每一轮，直到交付：</p><table tabindex="0"><thead><tr><th>阶段</th><th>变更控制在做什么</th></tr></thead><tbody><tr><td>需求 / 架构</td><td>定修改范围三栏、不做项、契约</td></tr><tr><td>开发</td><td>每轮只做范围内的一个子任务，越界先停</td></tr><tr><td>修复 / 重构</td><td>最小改动，不动无关代码</td></tr><tr><td>交付</td><td>diff 全量核对，遗留文件清理</td></tr></tbody></table><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to “核心内容”">​</a></h2><h3 id="修改范围三栏" tabindex="-1">修改范围三栏 <a class="header-anchor" href="#修改范围三栏" aria-label="Permalink to “修改范围三栏”">​</a></h3><p>每次任务都要写清三栏，落到具体文件路径：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>允许修改：</span></span>
<span class="line"><span>- backend/.../service/WorkOrderService.java</span></span>
<span class="line"><span>- web/src/api/mes.ts</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止修改：</span></span>
<span class="line"><span>- 任何已有接口路径与方法签名</span></span>
<span class="line"><span>- legacy/ 目录</span></span>
<span class="line"><span></span></span>
<span class="line"><span>必须保持兼容：</span></span>
<span class="line"><span>- GET /api/mes/work-orders 的返回结构</span></span>
<span class="line"><span>- 现有状态机的流转规则</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>AI 说「顺手把……也改了」、开始改依赖或公共模块，立即停。</p><h3 id="检查点" tabindex="-1">检查点 <a class="header-anchor" href="#检查点" aria-label="Permalink to “检查点”">​</a></h3><p>方案里预先约定哪些是检查点（如契约冻结后、数据层改完、接口联调前）。到检查点必须停下来等人确认，不自行通过。人只需回答：选哪个方案、加哪些边界、哪些风险不接受。</p><h3 id="失败分类" tabindex="-1">失败分类 <a class="header-anchor" href="#失败分类" aria-label="Permalink to “失败分类”">​</a></h3><p>不要一律重试。先分类再处理：</p><table tabindex="0"><thead><tr><th>类型</th><th>信号</th><th>处理</th></tr></thead><tbody><tr><td>代码错误</td><td>编译失败、断言失败、堆栈明确</td><td>可重试有限轮次</td></tr><tr><td>环境问题</td><td>缺服务、缺权限、缺数据</td><td>标受限，写替代检查</td></tr><tr><td>认知问题</td><td>反复改不对、改 A 坏 B</td><td>停手回分析影响范围</td></tr><tr><td>需求冲突</td><td>测试过但行为不符预期</td><td>停手交人确认</td></tr></tbody></table><h3 id="遗留文件清理" tabindex="-1">遗留文件清理 <a class="header-anchor" href="#遗留文件清理" aria-label="Permalink to “遗留文件清理”">​</a></h3><p>开发过程中产生的临时文件、调试脚本、备份文件、生成物，交付前统一清理：</p><ul><li>临时文件、<code>.bak</code>、<code>.tmp</code>、<code>~</code> 结尾的备份。</li><li>一次性调试脚本、临时日志。</li><li>被注释掉的旧代码、遗留 TODO。</li><li>构建产生的、不该进版本库的产物。</li></ul><p>清理也要在范围内：只删这次任务产生的，不删用户已有的文件。判断不了归属就问。</p><h2 id="可复制提示词" tabindex="-1">可复制提示词 <a class="header-anchor" href="#可复制提示词" aria-label="Permalink to “可复制提示词”">​</a></h2><details><summary><strong>变更范围检查</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请检查本次改动是否超出约定范围，只输出检查结果，不修改任何文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>修改范围三栏（粘贴）：</span></span>
<span class="line"><span>允许修改 / 禁止修改 / 必须保持兼容</span></span>
<span class="line"><span></span></span>
<span class="line"><span>当前 git status 和 git diff（粘贴）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请逐项检查：</span></span>
<span class="line"><span>1. 实际改动文件是否都在「允许修改」内。</span></span>
<span class="line"><span>2. 是否触碰「禁止修改」。</span></span>
<span class="line"><span>3. 是否有超出三栏的意外改动（依赖文件、公共模块、无关格式化）。</span></span>
<span class="line"><span>4. 「必须保持兼容」的内容是否真的没变（接口、字段、状态流转）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出：合规清单 + 越界项（文件:行号 + 说明）+ 需人确认的疑点。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div></details><details><summary><strong>遗留文件清理清单</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请扫描本次开发遗留的临时文件，输出清理清单，本轮只列清单，不删除。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>扫描范围：&lt;本次任务涉及的目录&gt;</span></span>
<span class="line"><span>任务起始时间或提交：&lt;用于判断哪些是本次产生的&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请列出：</span></span>
<span class="line"><span>1. 临时文件、备份文件（.bak / .tmp / ~ / .orig 等）。</span></span>
<span class="line"><span>2. 一次性调试脚本、临时日志、导出的数据文件。</span></span>
<span class="line"><span>3. 代码里注释掉的旧实现、遗留 TODO。</span></span>
<span class="line"><span>4. 构建产物中不该进版本库的部分。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每项标注：路径、判断为本次产生的依据、建议动作。</span></span>
<span class="line"><span>无法判断归属的一律标「需人确认」，不要列入自动清理。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div></details><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to “验收要点”">​</a></h2><ul><li>[ ] 修改范围三栏写清并落到文件路径。</li><li>[ ] 每轮改动在范围内，越界情况为零或已处理。</li><li>[ ] 检查点停下来等确认，没有被跳过。</li><li>[ ] 失败先分类，没有无限重试。</li><li>[ ] 遗留文件清理完，没有误删用户文件。</li></ul><p>回滚的方案与追踪见 <a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality/delivery-rollback.html">交付追踪与回滚</a>。</p>`,25)])])}const u=s(l,[["render",i]]);export{o as __pageData,u as default};
